  KEY `idx_payment_order_provider` (`tenant_id`,`provider_code`,`provider_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `payment_refund` (
